const awaitClosed = (socket: WebSocket): Promise<void> =>
  socket.readyState === WebSocket.CLOSED
    ? Promise.resolve()
    : new Promise<void>(resolve => socket.once('close', () => resolve()));

/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  const openClients = clients.splice(0);
  const activeServers = servers.splice(0);
  const serverSockets = activeServers.flatMap(hal => [...hal.wss.clients]);
  for (const client of openClients) client.terminate();
  await Promise.all([...openClients.map(awaitClosed), ...serverSockets.map(awaitClosed)]);
  for (const hal of activeServers) await hal.stop();
}

